[things]
# The floor starts on emergency lighting (circuit=emergency panels) until the
# plant room's breaker is thrown.
# type          x     y     angle
# Entrance lobby: two storeys, glazed, entrance doors on the west, the
# reception desk facing them, stairs up to a railed balcony along the north
coop_start      1.5   3.5   0
# Doors (prototype): glass doors from the lobby into the offices (staff
# pass: blue, on the reception counter), and a
# double office door from the corridor into the open plan (swings north, into it)
door_sliding    8.5   4.5   0     lock=blue
door_double     12.5  10.5  270
# The plant room (for now, the small room south of the corridor): facilities
# pass (red), which is on the boss's desk
door_hinged     11.5  12.5  90    lock=red
# The plant room's main breaker, against its south wall: restores the power
breaker         10.5  14.99 270
pass_blue       4.37  4.4   0
pass_red        4.2   10.3  0
reception_desk  4.6   4.0   180
# On the wall behind reception, above the glass doors (the wall's face is x = 8)
welcome_sign    7.99  4.5   180
# The lifts, in the lobby's south wall: call one (E) once the power's on, step
# in; when everyone's aboard the doors close and the floor is done
door_lift       2.5   7.5   270
door_lift       4.5   7.5   270
door_lift       6.5   7.5   270
